import json
with open('/app/resources/treasury_bulletin_1960_10.json') as f:
    data = json.load(f)
doc = data.get('document', {})
print(list(doc.keys())[:20])
sections = doc.get('sections', [])
print(f'Number of sections: {len(sections)}')
for i, s in enumerate(sections[:5]):
    if isinstance(s, dict):
        print(f'Section {i}:', list(s.keys()))
        for k, v in s.items():
            if isinstance(v, str):
                print(f'  {k}: {v[:100]}')
            elif isinstance(v, list):
                print(f'  {k}: list of {len(v)} items')
            elif isinstance(v, dict):
                print(f'  {k}: dict with keys {list(v.keys())[:5]}')
